CREATE TABLE IF NOT EXISTS users (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,email VARCHAR(254) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'student');
CREATE TABLE IF NOT EXISTS clubs (id INT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(80) NOT NULL,category VARCHAR(80) NOT NULL,initials VARCHAR(3) NOT NULL,color VARCHAR(20) NOT NULL,description TEXT NOT NULL,contact VARCHAR(254) NOT NULL,owner_id INT NULL,FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS events (id INT PRIMARY KEY AUTO_INCREMENT,title VARCHAR(100) NOT NULL,clubId INT NOT NULL,category VARCHAR(80) NOT NULL,date VARCHAR(10) NOT NULL,time VARCHAR(5) NOT NULL,location VARCHAR(80) NOT NULL,price DECIMAL(10,2) NOT NULL,capacity INT NOT NULL,description TEXT NOT NULL,artwork VARCHAR(20) NOT NULL,owner_id INT NULL,FOREIGN KEY(clubId) REFERENCES clubs(id),FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS likes (user_id INT NOT NULL,event_id INT NOT NULL,PRIMARY KEY(user_id,event_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS registrations (user_id INT NOT NULL,event_id INT NOT NULL,PRIMARY KEY(user_id,event_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS memberships (user_id INT NOT NULL,club_id INT NOT NULL,PRIMARY KEY(user_id,club_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(club_id) REFERENCES clubs(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(40) PRIMARY KEY,value VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (id INT PRIMARY KEY AUTO_INCREMENT,ip VARCHAR(64) NOT NULL,window_id BIGINT NOT NULL);
